theme.css:
/* theme: Red Tape Reel | Market red and tech's fall run on a ticker-tape page of glitches, with a chrome-silver trim for the gamer economy. */
/* mood: bad */
/* layout: hero=classic; tech-news=banner/grid-2; entertainment-news=numbered/masonry; sports=split/masonry; music-releases=plain/stack; stock-analysis=stat/grid-3; outlook=timeline/stack */
.diary-page {
  --paper: #1c0b0d;
  --paper-alt: #2a1214;
  --ink: #f7e8e2;
  --ink-soft: #d9c4be;
  --muted: #a58d86;
  --accent: #ff5c5c;
  --accent-ink: #1a0505;
  --rule: #4a2020;
  --font-display: var(--ff-bebas), sans-serif;
  --font-body: var(--ff-newsreader), Georgia, serif;
  --font-ui: var(--ff-plex-mono), ui-monospace, monospace;
}

@media (prefers-color-scheme: dark) {
  .diary-page {
    --paper: #1c0b0d;
    --paper-alt: #2a1214;
    --ink: #f7e8e2;
    --ink-soft: #d9c4be;
    --muted: #a58d86;
    --accent: #ff5c5c;
    --accent-ink: #1a0505;
    --rule: #4a2020;
  }
}

.diary-page {
  background:
    linear-gradient(180deg, transparent 0, transparent 2rem, var(--rule) 2rem, var(--rule) 2.1rem, transparent 2.1rem) repeat-y 1.5rem 0 / 100% 4rem,
    var(--paper);
}

.diary-page .diary-hero {
  background: var(--paper-alt);
  border-bottom: 2px solid var(--accent);
  box-shadow: inset 0 -1rem 2rem -2rem var(--accent);
}

.diary-page .diary-hero-inner {
  padding-block: 3rem 4.5rem;
}

.diary-page .diary-crumbs a {
  font-family: var(--font-ui);
  font-size: 0.8rem;
  letter-spacing: 0.12em;
  color: var(--muted);
}

.diary-page .diary-crumbs a::before {
  content: "⌖ ";
}

.diary-page .diary-kicker {
  font-family: var(--font-ui);
  font-size: 0.75rem;
  font-weight: 600;
  letter-spacing: 0.24em;
  text-transform: uppercase;
  color: var(--accent);
  display: inline-block;
  padding: 0.25rem 0.6rem;
  border: 1px solid var(--accent);
  border-radius: 0.2rem;
}

.diary-page .diary-title {
  font-family: var(--font-display);
  font-size: clamp(2.6rem, 7vw, 5.6rem);
  font-weight: 400;
  line-height: 0.95;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: var(--ink);
  max-width: 22ch;
}

.diary-page .diary-summary {
  font-family: var(--font-body);
  font-size: clamp(1.2rem, 2vw, 1.5rem);
  line-height: 1.55;
  color: var(--ink-soft);
  max-width: 48rem;
  border-left: 3px solid var(--accent);
  padding-left: 1.25rem;
}

.diary-page .diary-theme-note {
  font-family: var(--font-ui);
  font-size: 0.8rem;
  color: var(--muted);
}

.diary-page .diary-theme-name {
  background: var(--accent);
  color: var(--accent-ink);
  padding: 0.15rem 0.5rem;
  border-radius: 0.2rem;
  font-weight: 700;
  letter-spacing: 0.08em;
}

.diary-page .diary-toc {
  background: var(--paper);
  border-bottom: 1px solid var(--rule);
}

.diary-page .diary-toc-label,
.diary-page .diary-toc-number,
.diary-page .diary-section-number {
  color: var(--accent);
  font-family: var(--font-ui);
}

.diary-page .diary-toc-link,
.diary-page .diary-toc-top,
.diary-page .diary-toc-bottom {
  color: var(--muted);
  font-family: var(--font-ui);
  font-size: 0.8rem;
}

.diary-page .diary-toc-link:hover,
.diary-page .diary-toc-top:hover,
.diary-page .diary-toc-bottom:hover,
.diary-page .diary-toc-link.is-active {
  color: var(--ink);
}

.diary-page .diary-section {
  border-top-color: var(--rule);
}

.diary-page .diary-section-head {
  border-bottom: 1px solid var(--rule);
  padding-bottom: 1rem;
}

.diary-page .diary-section-title {
  font-family: var(--font-display);
  font-size: clamp(2rem, 4vw, 3rem);
  font-weight: 400;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--ink);
}

.diary-page .diary-card-title {
  font-family: var(--font-display);
  letter-spacing: 0.03em;
  text-transform: uppercase;
  font-size: clamp(1.3rem, 2vw, 1.6rem);
  font-weight: 400;
  color: var(--ink);
}

.diary-page .diary-prose {
  color: var(--ink-soft);
  font-size: 1.1rem;
  line-height: 1.7;
}

.diary-page .diary-prose a {
  color: var(--accent);
  border-bottom-color: var(--accent);
  font-family: var(--font-ui);
  font-size: 0.65em;
}

.diary-page .diary-prose a:hover {
  color: var(--ink);
}

.diary-page .diary-prose strong {
  color: var(--ink);
}

.diary-page .diary-prose blockquote {
  border-left-color: var(--accent);
  color: var(--ink);
}

.diary-page .diary-prose ul > li::before {
  background: var(--accent);
}

.diary-page .diary-prose ul > li {
  padding-left: 1.5rem;
}

.diary-page .diary-prose ol > li::marker {
  color: var(--accent);
}

.diary-page .diary-card-thread {
  border-color: var(--accent);
  color: var(--accent);
  font-family: var(--font-ui);
  font-size: 0.7rem;
  background: transparent;
  padding: 0.15rem 0.5rem;
  border-radius: 0;
  letter-spacing: 0.04em;
}

.diary-page .diary-card-thread:hover {
  background: var(--accent);
  color: var(--accent-ink);
}

.diary-page .diary-stories--stack > .diary-card--plain + .diary-card--plain {
  border-top-color: var(--rule);
}

.diary-page [data-section="tech-news"] .diary-card--banner .diary-card-inner {
  border-color: var(--rule);
  border-radius: 0;
  background: var(--paper-alt);
}

.diary-page [data-section="tech-news"] .diary-card--banner .diary-card-title {
  background: var(--accent);
  color: var(--accent-ink);
  font-size: 1.2rem;
  padding: 0.75rem 1.25rem;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  font-family: var(--font-display);
}

.diary-page [data-section="tech-news"] .diary-card--banner .diary-card-body {
  padding: 1.25rem;
}

.diary-page [data-section="tech-news"] .diary-card--banner .diary-card-thread {
  margin: 0.75rem 1.25rem 1.25rem;
}

.diary-page .diary-card--numbered .diary-card-index {
  font-family: var(--font-display);
  font-size: 3.8rem;
  font-weight: 400;
  color: var(--accent);
  letter-spacing: 0.02em;
  line-height: 0.85;
}

.diary-page .diary-card--numbered .diary-card-inner {
  border-bottom: 1px solid var(--rule);
  padding-bottom: 1.25rem;
}

.diary-page .diary-card--split .diary-card-inner {
  border-top-color: var(--accent);
  padding-top: 1.25rem;
}

.diary-page .diary-card--split .diary-card-title {
  font-size: 1.5rem;
}

.diary-page .diary-card--timeline .diary-card-inner::before {
  background: var(--rule);
}

.diary-page .diary-card--timeline .diary-card-inner::after {
  background: var(--accent);
  box-shadow: 0 0 0 3px var(--paper);
  border-radius: 0;
  width: 0.6rem;
  height: 0.6rem;
  left: 0.35rem;
}

.diary-page .diary-card--stat .diary-card-inner {
  border-top-color: var(--accent);
  padding-top: 1rem;
}

.diary-page .diary-card-figure {
  font-family: var(--font-display);
  font-weight: 400;
  letter-spacing: 0.02em;
  color: var(--accent);
  font-size: clamp(2.5rem, 12cqi, 4rem);
}

.diary-page .diary-markets-label {
  font-family: var(--font-ui);
  color: var(--muted);
  letter-spacing: 0.12em;
}

.diary-page .diary-markets {
  gap: 0.6rem;
}

.diary-page .diary-spark {
  background: var(--paper-alt);
  border: 1px solid var(--rule);
  border-radius: 0.25rem;
  font-family: var(--font-ui);
  position: relative;
}

.diary-page .diary-spark::before {
  content: "";
  position: absolute;
  inset: 0 0 auto 0;
  height: 3px;
  background: var(--accent);
}

.diary-page .diary-spark.is-down::before {
  background: var(--accent);
}

.diary-page .diary-spark.is-up::before {
  background: var(--muted);
}

.diary-page .diary-spark-label {
  color: var(--muted);
}

.diary-page .diary-spark-value {
  color: var(--ink);
}

.diary-page .diary-spark-change {
  color: var(--accent);
}

.diary-page .diary-spark-line {
  stroke: var(--accent);
  stroke-width: 1.5;
  fill: none;
}

.diary-page .diary-footer {
  border-top-color: var(--rule);
  font-family: var(--font-ui);
}

.diary-page .diary-footer a {
  color: var(--ink);
}

.diary-page .diary-footer a:hover {
  color: var(--accent);
}

.diary-page .diary-footer-meta {
  color: var(--muted);
}

@media (min-width: 1024px) {
  .diary-page .diary-toc-label {
    color: var(--muted);
  }
  .diary-page .diary-toc-list {
    border-left-color: var(--rule);
  }
  .diary-page .diary-toc-link.is-active {
    border-left-color: var(--accent);
  }
}

.diary-page .diary-section:first-child .diary-card--banner:first-child .diary-prose > p:first-of-type::first-letter {
  font-family: var(--font-display);
  font-size: 2.8em;
  line-height: 0.8;
  color: var(--accent);
}
